const Redis = require('ioredis');
const redis = new Redis();

const pipeline = redis.pipeline();

for (let i = 0; i < 1000; i++) {
  pipeline.set(`user:${i}:name`, `User ${i}`);
}

// All commands are sent in one network flush
const results = await pipeline.exec();
console.log(`Completed ${results.length} SET commands`);

// results is an array of [error, reply] tuples
results.forEach(([err, reply], index) => {
  if (err) console.error(`Failed at index ${index}:`, err);
